import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
import { getProduct } from './catalogue.js';
import { ok, fail } from './result.js';
import { nextInvoiceNumber } from './numbering.js';

/**
 * Create an invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number, discountPercent?: number }> }}
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: 'draft', lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) {
    return fail('CUSTOMER_NOT_FOUND');
  }

  const customer = customerResult.value;

  if (!isValidDate(issueDate)) {
    return fail('DATE_INVALID');
  }

  if (!Array.isArray(lines) || lines.length === 0) {
    return fail('NO_LINES');
  }

  const invoiceLines = [];
  for (const line of lines) {
    if (!Number.isInteger(line.qty) || line.qty <= 0) {
      return fail('QTY_INVALID');
    }

    const discountPercent = line.discountPercent !== undefined ? line.discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscount(discountPercent)) {
      return fail('DISCOUNT_INVALID');
    }

    const productResult = getProduct(line.sku);
    if (!productResult.ok) {
      return fail('UNKNOWN_SKU');
    }

    const product = productResult.value;
    invoiceLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: invoiceLines,
  });
}

/**
 * Calculate the total amount for a line (qty × unitPrice, in cents).
 * @param {{ qty: number, unitPrice: number }}
 * @returns {number}
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a line.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
 * @returns {number}
 */
export function lineDiscount(line) {
  const total = lineTotal(line);
  const percent = line.discountPercent ?? 0;
  const discount = total * percent / 100;
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a line (on amount after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }}
 * @returns {number}
 */
export function lineVAT(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const discountedAmount = Math.max(0, total - discount);
  const rate = line.vatRate ?? 0;
  const vat = discountedAmount * rate / 100;
  return Math.round(vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate?: number }> }}
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }}
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return { subtotal, discount, vat, total };
}

/**
 * Add a line to an invoice (or increment qty if SKU already exists).
 * @param {{ status: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} line
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  if (!Number.isInteger(qty) || qty <= 0) {
    return fail('QTY_INVALID');
  }

  const productResult = getProduct(sku);
  if (!productResult.ok) {
    return fail('UNKNOWN_SKU');
  }

  const newLines = invoice.lines.map((line) => ({ ...line }));
  const existingIndex = newLines.findIndex((line) => line.sku === sku);

  if (existingIndex >= 0) {
    newLines[existingIndex] = {
      ...newLines[existingIndex],
      qty: newLines[existingIndex].qty + qty,
    };
  } else {
    const customerResult = getCustomer(invoice.customerId);
    if (!customerResult.ok) {
      return fail('CUSTOMER_NOT_FOUND');
    }

    const customer = customerResult.value;
    const inputDiscount = discountPercent !== undefined ? discountPercent : TIER_DISCOUNTS[customer.tier];
    if (!isValidDiscount(inputDiscount)) {
      return fail('DISCOUNT_INVALID');
    }

    const product = productResult.value;
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: inputDiscount,
    });
  }

  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Remove a line from an invoice by SKU.
 * @param {{ status: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: { status: string, lines: Array } } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const index = invoice.lines.findIndex((line) => line.sku === sku);
  if (index < 0) {
    return fail('LINE_NOT_FOUND');
  }

  if (invoice.lines.length === 1) {
    return fail('NO_LINES');
  }

  const newLines = invoice.lines.filter((_, i) => i !== index);
  return ok({
    ...invoice,
    lines: newLines,
  });
}

/**
 * Issue an invoice (assign a number and change status to 'issued').
 * @param {{ status: string, issueDate: string }} invoice
 * @param {Array<string>} existingNumbers - Invoice numbers already issued
 * @returns {{ ok: true, value: { status: string, number: string } } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  if (invoice.status !== 'draft') {
    return fail('NOT_DRAFT');
  }

  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    ...invoice,
    number,
    status: 'issued',
  });
}

function isValidDate(dateString) {
  if (typeof dateString !== 'string') return false;
  if (!/^\d{4}-\d{2}-\d{2}$/.test(dateString)) return false;

  const date = new Date(dateString + 'T00:00:00Z');
  if (isNaN(date.getTime())) return false;

  const [year, month, day] = dateString.split('-').map(Number);
  return (
    date.getUTCFullYear() === year &&
    date.getUTCMonth() === month - 1 &&
    date.getUTCDate() === day
  );
}

function isValidDiscount(percent) {
  return typeof percent === 'number' && percent >= 0 && percent <= 100;
}

