    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 1 }],
  }).value;

  assert.deepEqual(addLine(invoice, { sku: 'COPY-HOUR', qty: 0 }), { ok: false, error: 'QTY_INVALID' });
